import java.io.InputStream;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.Arrays;

public class Main {
    static class Edge implements Comparable<Edge> {
        int u, v, weight;

        Edge(int u, int v, int weight) {
            this.u = u;
            this.v = v;
            this.weight = weight;
        }

        @Override
        public int compareTo(Edge o) {
            return Integer.compare(o.weight, this.weight); // Ordem decrescente para Árvore Geradora Máxima
        }
    }

    static class DSU {
        int[] parent;

        DSU(int n) {
            parent = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                parent[i] = i;
            }
        }

        int find(int i) {
            if (parent[i] == i)
                return i;
            return parent[i] = find(parent[i]);
        }

        boolean union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                parent[rootI] = rootJ;
                return true;
            }
            return false;
        }
    }

    // Grafo da MST
    static int[] head, to, next, weight;
    static int edgeCount = 0;

    static void addEdge(int u, int v, int w) {
        to[edgeCount] = v;
        weight[edgeCount] = w;
        next[edgeCount] = head[u];
        head[u] = edgeCount++;

        to[edgeCount] = u;
        weight[edgeCount] = w;
        next[edgeCount] = head[v];
        head[v] = edgeCount++;
    }

    static final int LOGN = 18;
    static int[][] up;
    static int[][] minWeight;
    static int[] depth;

    static void dfs(int u, int p, int d, int w) {
        depth[u] = d;
        up[0][u] = p;
        minWeight[0][u] = w;

        for (int i = 1; i < LOGN; i++) {
            up[i][u] = up[i - 1][up[i - 1][u]];
            minWeight[i][u] = Math.min(minWeight[i - 1][u], minWeight[i - 1][up[i - 1][u]]);
        }

        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            if (v != p) {
                dfs(v, u, d + 1, weight[e]);
            }
        }
    }

    static int query(int u, int v) {
        int ans = Integer.MAX_VALUE;

        if (depth[u] < depth[v]) {
            int temp = u;
            u = v;
            v = temp;
        }

        // Subir 'u' até a mesma profundidade de 'v'
        for (int i = LOGN - 1; i >= 0; i--) {
            if (depth[u] - (1 << i) >= depth[v]) {
                ans = Math.min(ans, minWeight[i][u]);
                u = up[i][u];
            }
        }

        if (u == v) return ans;

        for (int i = LOGN - 1; i >= 0; i--) {
            if (up[i][u] != up[i][v]) {
                ans = Math.min(ans, Math.min(minWeight[i][u], minWeight[i][v]));
                u = up[i][u];
                v = up[i][v];
            }
        }

        ans = Math.min(ans, Math.min(minWeight[0][u], minWeight[0][v]));
        return ans;
    }

    public static void main(String[] args) throws IOException {
        FastScanner sc = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = sc.nextInt();
        int b = sc.nextInt();

        Edge[] edges = new Edge[b];
        for (int i = 0; i < b; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            int p = sc.nextInt();
            edges[i] = new Edge(u, v, p);
        }

        Arrays.sort(edges);

        DSU dsu = new DSU(n);

        head = new int[n + 1];
        Arrays.fill(head, -1);
        to = new int[2 * n];
        weight = new int[2 * n];
        next = new int[2 * n];
        edgeCount = 0;

        int mstEdges = 0;
        for (int i = 0; i < b; i++) {
            if (dsu.union(edges[i].u, edges[i].v)) {
                addEdge(edges[i].u, edges[i].v, edges[i].weight);
                mstEdges++;
                if (mstEdges == n - 1) break;
            }
        }

        up = new int[LOGN][n + 1];
        minWeight = new int[LOGN][n + 1];
        depth = new int[n + 1];

        dfs(1, 1, 0, Integer.MAX_VALUE);

        int c = sc.nextInt();
        for (int i = 0; i < c; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            out.println(query(u, v));
        }

        out.flush();
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (c <= ' ' && c != -1) {
                c = readByte();
            }
            if (c == -1) return -1;
            int res = 0;
            while (c > ' ') {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + (c - '0');
                }
                c = readByte();
            }
            return res;
        }
    }
}
